import numpy as np
from scipy.optimize import minimize

def objective(v):
    x, y, z = v
    return 9*x*y*z - 2*(x+y+z)

def constraint(v):
    return np.sum(v**2) - 1

cons = {'type': 'eq', 'fun': constraint}

min_val = float('inf')
# Test several starting points
for i in range(100):
    start = np.random.uniform(-1, 1, 3)
    start = start / np.linalg.norm(start)
    res = minimize(objective, start, constraints=cons)
    if res.success:
        min_val = min(min_val, res.fun)

print(f"Refined minimum: {min_val}")
